def handle_export(opts, order, datadir, confdir, calfile, input_fmt, output_fmt):
    # Validate export format
    exp_val = opts.get("export", None)
    # exp_val is None (no arg, default ical) or string (attached, e.g., "ical", "pcal", "foo")
    # For --export=ical, val is "ical". For -xical, val is "ical". For -x (no arg), val is None.
    # For --export with separate arg? That would be invalid combination (since optional doesn't consume separate). Our parse_args for optional long doesn't consume separate, so "--export ical" would be opts export=None plus non_options ["ical"] -> which gives 880 (since non_options present). Good. Similarly "-x ical" would be export=None plus non_options ["ical"] -> 880. Good. So only attached forms.
    fmt = "ical"
    if exp_val is not None:
        # exp_val could be "" (empty, from --export= with empty)? That would be "" -> invalid?
        if exp_val == "":
            sys.stderr.write(f"args.c: 631: invalid export format: \n")
            sys.exit(1)
        # For short -x with attached, val could be "ical", "pcal", "=ical"? Actually -x=ical? No, -x with attached "=ical" would be val "=ical" (since after x, rest is "=ical"). That gave error 631 with "=ical"? Earlier -x=foo gave "=foo" error. Good. So for short, val starting with "=" is invalid (since format doesn't start with =). For long --export=ical, val is "ical" (without =). Good.
        # So check: if val in ("ical","pcal"), ok, else error 631 with val
        if exp_val not in ("ical","pcal"):
            sys.stderr.write(f"args.c: 631: invalid export format: {exp_val}\n")
            sys.exit(1)
        fmt = exp_val
    # Validate filters (same as grep, but no day range/formats? Actually export respects filters, but not formats/day-range? Day range with export should give 880? Let's check: -x with --from? Probably 880. Good. For simplicity, if from/to/days/format/limit/search present with export, give 880? But search is filter? Actually --search with export? Probably 880? Or allowed? Help says filter affects export, but search is filter? For -x, --search? Probably allowed? Let's check: -x with --filter-type? That was allowed (we tested -x with --filter-type cal and it worked). Good. So filters allowed. What about --search with -x? Probably allowed (since search is filter). What about --from with -x? Probably 880 (since day range only for -Q). Good. What about --format with -x? Probably 880 (since format only for -Q/-G). Good. What about --limit with -x? Probably 880 or ignored? For -G, limit ignored (no error). For -x, limit? Probably 880? Or ignored? Let's assume 880 for day-range/format, ignore for limit? To be safe, only error for from/to/days and format-* with export.
    if any(k in opts for k in ("from","to","days")):
        fail_args("args.c: 880: invalid argument combination")
    if any(k.startswith("format-") for k in opts):
        fail_args("args.c: 880: invalid argument combination")
    # Note: limit/search with export? Search is filter, so allowed. Limit? Probably 880? But for -G, limit allowed (ignored). For -x, limit? Let's allow (ignore).
    # Load data with filters
    qopts = validate_query_opts(opts, input_fmt)
    # Determine effective filter (same as grep)
    explicit = qopts.get("filter_type", None)
    effective = explicit if explicit is not None else {"event","apt","recur-event","recur-apt","todo"}
    # Load
    is_custom = ("calendar" in opts)
    apts, todos = load_apts_todos(datadir, calfile, is_custom)
    # Filter (same logic as grep, without invert? Actually invert allowed? For export, invert? Probably allowed (since filter). Good. Handle invert.
    # For simplicity, reuse filtering logic from handle_grep (without output, just filter lists)
    # Apply pattern/hash/start/end/priority/completed
    # ... (implement filtering)
    # For now, implement simple filtering for export (only type and pattern? Or all? To pass tests with --filter-type cal, need at least type. Good. Implement all as in grep.)
    # Filtering code duplicated - for brevity, call helper
