    quiet = ("quiet" in opts)
    export_uid = ("export-uid" in opts)
    read_only = ("read-only" in opts)  # read-only doesn't affect export? Probably still exports (no save). Good.
    if fmt == "ical":
        out = export_ical(filtered_apts, filtered_todos, export_uid, datadir)
        sys.stdout.write(out)
    else:
        out = export_pcal(filtered_apts, filtered_todos, datadir)
        sys.stdout.write(out)
    sys.exit(0)

def filter_for_export(apts, todos, opts, qopts, effective):
    # Returns filtered lists
    patterns = []
    if "filter-pattern" in opts:
        patterns.append(opts["filter-pattern"])
    if "search" in opts:
        patterns.append(opts["search"])
    import re as _re
    compiled = []
    for p in patterns:
        try:
            compiled.append(_re.compile(p))
        except:
            pass
    filter_hash = qopts.get("filter_hash", None)
    invert = qopts.get("filter_invert", False)
    todo_prio = qopts.get("filter_priority", None)
    todo_comp = qopts.get("filter_completed", False)
    todo_uncomp = qopts.get("filter_uncompleted", False)
    f_apts = []
    for a in apts:
        is_recur = a.recur is not None
        typ = ("recur-event" if is_recur else "event") if a.is_event else ("recur-apt" if is_recur else "apt")
        m = (typ in effective)
        if m:
            for rx in compiled:
                if not rx.search(a.desc):
                    m=False
                    break
        if m and filter_hash is not None:
            neg = filter_hash.startswith("!")
            h = filter_hash[1:] if neg else filter_hash
            if neg:
                if a.hash.startswith(h):
                    m=False
            else:
                if not a.hash.startswith(h):
                    m=False
        if m:
            s=a.start; e=a.end
            if "filter-start-from" in qopts and not (s>=qopts["filter-start-from"]):
                m=False
            if "filter-start-to" in qopts and not (s<=qopts["filter-start-to"]):
                m=False
            if "filter-start-after" in qopts and not (s>qopts["filter-start-after"]):
                m=False
            if "filter-start-before" in qopts and not (s<qopts["filter-start-before"]):
                m=False
            if "filter-start-range" in qopts:
                d1,d2=qopts["filter-start-range"]
                if not (d1<=s<=d2):
                    m=False
            if "filter-end-from" in qopts and not (e>=qopts["filter-end-from"]):
                m=False
            if "filter-end-to" in qopts and not (e<=qopts["filter-end-to"]):
                m=False
            if "filter-end-after" in qopts and not (e>qopts["filter-end-after"]):
                m=False
            if "filter-end-before" in qopts and not (e<qopts["filter-end-before"]):
                m=False
            if "filter-end-range" in qopts:
                d1,d2=qopts["filter-end-range"]
                if not (d1<=e<=d2):
                    m=False
        if invert:
            m=not m
        if m:
            f_apts.append(a)
    f_todos=[]
    for t in todos:
        m=("todo" in effective)
        if m:
            for rx in compiled:
                if not rx.search(t.desc):
                    m=False
                    break
        if m and filter_hash is not None:
            neg=filter_hash.startswith("!")
            h=filter_hash[1:] if neg else filter_hash
            if neg:
                if t.hash.startswith(h):
                    m=False
            else:
                if not t.hash.startswith(h):
                    m=False
        if m and todo_prio is not None:
            if t.orig_prio!=todo_prio:
                m=False
        if m:
            if todo_comp and not todo_uncomp:
                if not t.completed:
                    m=False
            elif todo_uncomp and not todo_comp:
                if t.completed:
                    m=False
        if invert:
            m=not m
        if m:
            f_todos.append(t)
    return f_apts, f_todos

PYEOF
