            sys.exit(1)
        # For short -x with attached, val could be "ical", "pcal", "=ical"? Actually -x=ical? No, -x with attached "=ical" would be val "=ical" (since after x, rest is "=ical"). That gave error 631 with "=ical"? Earlier -x=foo gave "=foo" error. Good. So for short, val starting with "=" is invalid (since format doesn't start with =). For long --export=ical, val is "ical" (without =). Good.
        # So check: if val in ("ical","pcal"), ok, else error 631 with val
        if exp_val not in ("ical","pcal"):
