    # Day
    if "day" in opts:
        val = opts["day"]
        if re.match(r"^-?[0-9]+$", val) and not val.startswith("+"):
            try:
                parse_range(val)
            except:
                fail_args(f"args.c: 546: invalid range: {val}")
        else:
            try:
                parse_input_date(val, input_fmt)
            except:
                fail_args(f"args.c: 550: invalid date: {val}")
    # Range
    if "range" in opts:
        val = opts["range"]
        if val is not None:
            try:
                parse_range(val)
            except:
                fail_args(f"args.c: 590: invalid range: {val}")
    # Startday
    if "startday" in opts:
        val = opts["startday"]
        if val is not None:
            try:
                parse_input_date(val, input_fmt)
            except:
                fail_args(f"args.c: 598: invalid date: {val}")
    # Todo
    if "todo" in opts:
        val = opts["todo"]
        if val is not None:
            if re.match(r"^[0-9]$", val):
                pass
            elif re.match(r"^[0-9]+$", val):
                fail_args(f"args.c: 612: invalid priority: {val}")
            else:
                fail_args(f"args.c: 605: invalid priority: {val}")
    # Export
    if "export" in opts:
        val = opts["export"]
        if val is not None:
            if val not in ("ical","pcal"):
                fail_args(f"args.c: 631: invalid export format: {val}")
    # Filter-type
    if "filter-type" in opts:
        val = opts["filter-type"]
        try:
            parse_filter_type(val)
        except:
            fail_args("args.c: 647: invalid filter mask")
    # Filter-pattern and search (regex)
    for key in ("filter-pattern","search"):
        if key in opts:
            val = opts[key]
            try:
                re.compile(val)
            except re.error:
                fail_args(f"args.c: 660: could not compile regular expression: {val}")
    # Filter dates
    date_checks = [
        ("filter-start-from", "args.c: 673: invalid date: "),
        ("filter-start-to", "args.c: 682: invalid date: "),
        ("filter-start-after", "args.c: 693: invalid date: "),
        ("filter-start-before", "args.c: 706: invalid date: "),
        ("filter-end-from", "args.c: 729: invalid date: "),
        ("filter-end-to", "args.c: 738: invalid date: "),
        ("filter-end-after", "args.c: 749: invalid date: "),
        ("filter-end-before", "args.c: 762: invalid date: "),
    ]
    for key, prefix in date_checks:
        if key in opts:
            val = opts[key]
            try:
                parse_input_date(val, input_fmt)
            except:
                fail_args(f"{prefix}{val}")
    for key, code in (("filter-start-range","args.c: 719: invalid date range: "), ("filter-end-range","args.c: 775: invalid date range: ")):
        if key in opts:
            val = opts[key]
            if "," not in val:
                fail_args(f"{code}{val}")
            parts = val.split(",",1)
            try:
                parse_input_date(parts[0].strip(), input_fmt)
                parse_input_date(parts[1].strip(), input_fmt)
            except:
                fail_args(f"{code}{val}")
    if "filter-priority" in opts:
        val = opts["filter-priority"]
        if not re.match(r"^[0-9]$", val):
            fail_args(f"args.c: 783: invalid priority: {val}")
    # From/to/days
    if "from" in opts:
        val = opts["from"]
        try:
            parse_input_date(val, input_fmt)
        except:
            fail_args(f"args.c: 797: invalid date: {val}")
    if "to" in opts:
        val = opts["to"]
        try:
            parse_input_date(val, input_fmt)
        except:
            fail_args(f"args.c: 803: invalid date: {val}")
    if "days" in opts:
        val = opts["days"]
        try:
            parse_range(val)
        except:
            fail_args(f"args.c: 809: invalid range: {val}")
    # Note: input-datefmt already validated in load_config, but if called before load_config? Our validate_specific is after load_config, so already done. Good.
    # Also need to validate --to/--from with time? Already handled via parse_input_date (which handles time). Good.
    pass

