def validate_specific(opts, input_fmt):
    # Validate all options that have specific error codes, before combination checks
    # This includes: day, range, startday, todo, export, filter-type, filter-pattern/search, filter-hash? (no), filter-start/end, filter-priority, from/to/days, input-datefmt (already done), etc.
    # For each, if present and invalid, exit with appropriate code.
